    let body=element('UDX.EDXF.QUANTITY_MIN',p.min)+element('UDX.EDXF.QUANTITY_MAX',p.max)+element('UDX.EDXF.PACKING_UNIT_CODE',p.code)+localizedElements('UDX.EDXF.PACKING_UNIT_NAME',p.name,profile);
