    corrections:catalog.db.prepare('SELECT c.record_json FROM catalog_supplier_corrections c JOIN catalog_supplier_plans p ON p.id=c.plan_id WHERE p.catalog_id=? ORDER BY c.id').all(catalogId).map(parse),
